param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference = 'Stop'
if ([Threading.Thread]::CurrentThread.ApartmentState -ne [Threading.ApartmentState]::STA) { throw 'Run with powershell.exe -STA.' }
$halcon = 'C:\Program Files\MVTec\HALCON-20.11-Progress'
$env:PATH = (Join-Path $halcon 'bin\x64-win64') + ';' + $env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll')) | Out-Null
$assembly = [Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$ok,[string]$message){if(-not$ok){throw "Assertion failed: $message"}}
function Polygon([double[]]$rows,[double[]]$columns){[HalconDotNet.HObject]$x=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$x,[HalconDotNet.HTuple]$rows,[HalconDotNet.HTuple]$columns);$x}
function Concat($objects){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($one in $objects){[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{if($null-ne$combined){$combined.Dispose()}}};Write-Output -NoEnumerate $all}

$temp=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s47-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$storeType=$assembly.GetType('HalconWinFormsDemo.Services.BatchTraceStore',$true)
$recordType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceRecord',$true);$itemType=$assembly.GetType('HalconWinFormsDemo.Models.VmImageBatchTraceItem',$true);$toolResultType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceToolResultData',$true);$outputDataType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceToolOutputData',$true);$layerType=$assembly.GetType('HalconWinFormsDemo.Models.VmBatchTraceLayerSnapshotData',$true)
$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$mainType.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$name){$f=$mainType.GetField($name,$all);if($null-eq$f){throw "Missing field $name"};$v=$f.GetValue($window);Write-Output -NoEnumerate $v}
function Tool([string]$kind,[string]$name){$mainType.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Out($tool,[string]$port){$value=$null;if(-not$tool.TryGetOutputValue($port,[ref]$value)){throw "Missing output $port"};$value}

# A: persist only Number/String summaries, load across restart, filter/search/link, legacy empty state, and preserve live selection.
$flow=Field 'flowTools';$mainType.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$source=Tool SubpixelEdgeExtraction 'Edge Producer';$filter=Tool XldAreaDirectionFilter 'Area Direction';$judge=Tool NumericJudge 'Final Judge';$flow.Add($source);$flow.Add($filter);$flow.Add($judge)
$source.ResultCode='OK';$source.ElapsedMilliseconds=1.25;$source.SetOutputValue('ContourCount',[double]4);$filter.ResultCode='NG';$filter.ElapsedMilliseconds=2.5;$filter.ErrorMessage='area rejected';$filter.SetOutputValue('ContourCount',[double]0);$filter.SetOutputValue('OriginalIndices','[]');$judge.ResultCode='ERROR';$judge.ErrorMessage='test error';$judge.SetOutputValue('ResultCode','ERROR')
$captured=$mainType.GetMethod('CaptureBatchTraceToolResults',$private).Invoke($window,@());Assert($captured.Count-eq3) 'Per-tool capture count/order failed';Assert($captured[1].ToolId-eq$filter.ToolId-and$captured[1].Outputs.Count-eq2) 'Tool identity or persistable outputs missing';Assert(($captured|ForEach-Object Outputs|ForEach-Object DataType|Where-Object{$_-notin@('Number','String')}).Count-eq0) 'Runtime object type leaked into trace JSON'
$store=[Activator]::CreateInstance($storeType,[object[]]@($temp.ToString()));$record=[Activator]::CreateInstance($recordType);$record.BatchId='S47-TRACE';$record.RecipeName='S47';$record.StartedAtUtc=[DateTime]::UtcNow.ToString('O');$record.CompletedAtUtc=$record.StartedAtUtc;$record.Items=New-Object "System.Collections.Generic.List[$itemType]";$item=[Activator]::CreateInstance($itemType);$item.Sequence=0;$item.FileName='sample.png';$item.State='NG';$item.ResultCode='NG';$item.ToolResults=$captured;$record.Items.Add($item);$store.Save($record)|Out-Null;$loaded=$store.LoadAll().Records[0];Assert($loaded.SchemaVersion-eq3-and$loaded.Items[0].ToolResults.Count-eq3-and$loaded.Items[0].ToolResults[1].ErrorMessage-eq'area rejected') 'Cross-restart result detail persistence failed'
$legacy=[Activator]::CreateInstance($recordType);$legacy.BatchId='LEGACY';$legacy.Items=New-Object "System.Collections.Generic.List[$itemType]";$legacyItem=[Activator]::CreateInstance($itemType);$legacy.Items.Add($legacyItem);$legacy.Normalize();Assert($legacy.Items[0].ToolResults.Count-eq0) 'Legacy trace did not normalize to empty details'
$corrupt=[Activator]::CreateInstance($toolResultType);$corrupt.Sequence=-1;$corrupt.ElapsedMilliseconds=[double]::NaN;$corrupt.Outputs=New-Object "System.Collections.Generic.List[$outputDataType]";$corrupt.Outputs.Add($null);$corrupt.Normalize(0);Assert($corrupt.Sequence-eq0-and$corrupt.ElapsedMilliseconds-eq0-and$corrupt.Outputs.Count-eq0-and$corrupt.ToolName.Length-gt0) 'Corrupt detail degradation failed'
$mainType.GetField('historicalBatchItem',$private).SetValue($window,$loaded.Items[0]);$selectedBefore=(Field 'FlowToolList').SelectedItem=$filter;(Field 'HistoricalToolResultSearchTextBox').Text='area';(Field 'HistoricalToolResultFilterComboBox').SelectedValue='NG';$mainType.GetMethod('RefreshHistoricalToolResults',$private).Invoke($window,@())|Out-Null;Assert((Field 'HistoricalToolResultList').Items.Count-eq1) 'Historical search/result filter failed';Assert([object]::ReferenceEquals($selectedBefore,(Field 'FlowToolList').SelectedItem)) 'Historical detail changed live tool selection'
foreach($name in @('HistoricalToolResultList','HistoricalToolResultSearchTextBox','HistoricalToolResultFilterComboBox','HistoricalToolResultStateText')){Assert($null-ne(Field $name)) "$name missing"}
Assert([object]::ReferenceEquals((Field 'BatchTraceGrid').ItemsSource,(Field 'ProductionBatchTraceGrid').ItemsSource)) 'Development/production trace data source diverged'
$historyLayerType=$mainType.GetNestedType('HistoricalLayerSnapshot',[Reflection.BindingFlags]'NonPublic');$layers=Field 'historicalLayers';$layers.Clear();foreach($id in @($filter.ToolId,'OTHER')){$meta=[Activator]::CreateInstance($layerType);$meta.ToolId=$id;$meta.ToolName=$id;$meta.PortName='XLD';$meta.DataType='XLD';$layer=[Activator]::CreateInstance($historyLayerType,$true);$historyLayerType.GetProperty('Metadata').SetValue($layer,$meta,$null);$historyLayerType.GetProperty('IsVisible').SetValue($layer,$true,$null);$layers.Add($layer)};$button=New-Object Windows.Controls.Button;$button.Tag=$captured[1].PSObject.BaseObject;$mainType.GetMethod('HistoricalToolResultLinkButton_Click',$private).Invoke($window,[object[]]@($button.PSObject.BaseObject,$null))|Out-Null;Assert($layers[0].IsVisible-and-not$layers[1].IsVisible) 'Historical tool-to-layer linkage failed'
$mainType.GetField('historicalBatchItem',$private).SetValue($window,$legacy.Items[0]);(Field 'HistoricalToolResultSearchTextBox').Text='';(Field 'HistoricalToolResultFilterComboBox').SelectedValue='All';$mainType.GetMethod('RefreshHistoricalToolResults',$private).Invoke($window,@())|Out-Null;Assert((Field 'HistoricalToolResultList').Items.Count-eq0-and(Field 'HistoricalToolResultStateText').Text.Length-gt0) 'Legacy empty state failed'

# B: real area_center_xld, positive/negative direction, inclusive boundary, open/degenerate skip, managed outputs and downstream.
$filterKind=[Enum]::Parse($kindType,'XldAreaDirectionFilter');$inputs=$metadataType.GetMethod('GetInputPorts',$static).Invoke($null,[object[]]@($filterKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$static).Invoke($null,[object[]]@($filterKind));Assert(($inputs|Where-Object PortName -eq XLD).Count-eq1) 'Typed XLD input missing';Assert(($outputs|Where-Object PortName -eq MeanArea).DataType-eq'Number'-and($outputs|Where-Object PortName -eq OriginalIndices).DataType-eq'String') 'Typed area/filter outputs missing'
$clockwise=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,10,10,0,0));$counter=Polygon ([double[]]@(0,10,10,0,0)) ([double[]]@(0,0,10,10,0));$open=Polygon ([double[]]@(0,0,10)) ([double[]]@(0,10,10));$degenerate=Polygon ([double[]]@(0,0,0,0)) ([double[]]@(0,5,10,0));$input=Concat @($clockwise,$counter,$open,$degenerate);foreach($x in @($clockwise,$counter,$open,$degenerate)){$x.Dispose()}
$areaTool=Tool XldAreaDirectionFilter 'S47 Area Direction';$flow.Add($areaTool);$run=$mainType.GetMethod('RunXldAreaDirectionFilterTool',$private);function RunArea($x){try{$run.Invoke($window,[object[]]@($areaTool,$x.PSObject.BaseObject))}catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
  try{$areaTool.Parameters.XldAreaMinimum=100;$areaTool.Parameters.XldAreaMaximum=100;$areaTool.Parameters.XldAreaClosureTolerance=0;$areaTool.Parameters.XldAreaDirectionMode='All';$result=RunArea $input;Assert($result.ResultCode-eq'OK'-and(Out $areaTool OriginalIndices)-eq'[1,2]'-and[int](Out $areaTool InputOpenCount)-eq1-and[int](Out $areaTool DegenerateCount)-eq1) 'Inclusive area or skip policy failed';Assert([int](Out $areaTool ClockwiseCount)-eq1-and[int](Out $areaTool CounterclockwiseCount)-eq1-and[Math]::Abs([double](Out $areaTool MeanArea)-100)-lt.0001) 'Direction/area statistics failed';$old=Out $areaTool XLD;$areaTool.Parameters.XldAreaDirectionMode='Clockwise';RunArea $input|Out-Null;Assert((Out $areaTool OriginalIndices)-eq'[1]'-and$old.IsDisposed) 'Clockwise or old snapshot release failed';$areaTool.Parameters.XldAreaDirectionMode='Counterclockwise';RunArea $input|Out-Null;Assert((Out $areaTool OriginalIndices)-eq'[2]') 'Counterclockwise mapping failed';[HalconDotNet.HTuple]$count=$null;[HalconDotNet.HOperatorSet]::CountObj($input,[ref]$count);Assert($count.I-eq4) 'Upstream ownership changed'}finally{$input.Dispose()}
  $selfIntersecting=Polygon ([double[]]@(0,10,0,10,0)) ([double[]]@(0,10,10,0,0));try{$areaTool.Parameters.XldAreaMinimum=0;$areaTool.Parameters.XldAreaMaximum=1000;$areaTool.Parameters.XldAreaDirectionMode='All';$selfResult=RunArea $selfIntersecting;Assert($selfResult.ResultCode-eq'NG'-and[int](Out $areaTool DegenerateCount)-eq1-and[int](Out $areaTool ContourCount)-eq0) 'Self-intersecting contour was not rejected'}finally{$selfIntersecting.Dispose()}
  [HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);try{$areaTool.Parameters.XldAreaDirectionMode='All';$emptyResult=RunArea $empty;Assert($emptyResult.ResultCode-eq'NG'-and[int](Out $areaTool ContourCount)-eq0) 'Empty input semantics failed'}finally{$empty.Dispose()}
$areaTool.Parameters.XldAreaMinimum=10;$areaTool.Parameters.XldAreaMaximum=5;Assert(-not[string]::IsNullOrWhiteSpace($areaTool.Parameters.Validate($filterKind))) 'Invalid area range accepted';$areaTool.Parameters.XldAreaMinimum=0;$areaTool.Parameters.XldAreaMaximum=100;$areaTool.Parameters.XldAreaClosureTolerance=-1;Assert(-not[string]::IsNullOrWhiteSpace($areaTool.Parameters.Validate($filterKind))) 'Invalid closure tolerance accepted'
$producer=Tool XldPointClosureFilter 'Area Source';$chainFilter=Tool XldAreaDirectionFilter 'Area Chain';$judgeChain=Tool NumericJudge 'Area Count Judge';$chainFilter.Parameters.XldAreaMinimum=99;$chainFilter.Parameters.XldAreaMaximum=101;$chainFilter.Parameters.XldAreaDirectionMode='All';$chainFilter.Parameters.XldAreaClosureTolerance=0;$chainFilter.SetInputBinding('XLD',$producer.ToolId,'XLD');$judgeChain.SetInputBinding('Value',$chainFilter.ToolId,'ContourCount');$judgeChain.InputToolId=$chainFilter.ToolId;$judgeChain.InputPortName='ContourCount';$judgeChain.NumericLowerLimit=2;$judgeChain.NumericUpperLimit=2;$flow.Add($producer);$flow.Add($chainFilter);$flow.Add($judgeChain);$cw=Polygon ([double[]]@(0,0,10,10,0)) ([double[]]@(0,10,10,0,0));$ccw=Polygon ([double[]]@(0,10,10,0,0)) ([double[]]@(0,0,10,10,0));$chainInput=Concat @($cw,$ccw);$cw.Dispose();$ccw.Dispose();try{$producer.SetOutputValue('XLD',$snapshotType.GetMethod('Create',$static).Invoke($null,[object[]]@($chainInput.PSObject.BaseObject,$producer.ToolId,$producer.InstanceName,'XLD')));$producer.ResultCode='OK'}finally{$chainInput.Dispose()};$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$execute.Invoke($window,[object[]]@($chainFilter,'S47 chain'))|Out-Null;$execute.Invoke($window,[object[]]@($judgeChain,'S47 chain'))|Out-Null;Assert($chainFilter.ResultCode-eq'OK'-and$judgeChain.ResultCode-eq'OK') 'Real XLD/Number downstream chain failed';$released=Out $producer XLD;$released.Dispose();$failed=$false;try{$execute.Invoke($window,[object[]]@($chainFilter,'released upstream'))|Out-Null}catch{$failed=$true};Assert $failed 'Released upstream XLD was accepted'
$areaTool.Parameters.XldAreaMinimum=0;$areaTool.Parameters.XldAreaMaximum=100;$areaTool.Parameters.XldAreaClosureTolerance=0;$areaTool.Parameters.XldAreaDirectionMode='Clockwise';(Field 'FlowToolList').SelectedItem=$areaTool;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($areaTool))|Out-Null;Assert((Field 'DockXldAreaDirectionFilterPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldAreaDirectionModeComboBox').SelectedValue-eq'Clockwise') 'Dock config synchronization failed'
$recipe=$mainType.GetMethod('CaptureRecipe',$private).Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object{$_.ToolId-eq$areaTool.ToolId}|Select-Object -First 1;if($null-eq$saved){throw ('Recipe kinds: '+(($recipe.ToolFlow|ForEach-Object ToolType)-join','))};Assert($saved.Parameters.XldAreaDirectionMode-eq'Clockwise'-and$saved.Parameters.XldAreaClosureTolerance-eq0) ("Recipe persistence failed: direction=$($saved.Parameters.XldAreaDirectionMode), tolerance=$($saved.Parameters.XldAreaClosureTolerance)")

$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output 'S47 historical per-tool results and HALCON XLD area/direction filter smoke tests passed.'
